/* Extended project dashboard: measured checkpoint data, distinct from code inventory. */
(async()=>{
 const root=document.getElementById('cc-development-expanded');if(!root)return;
 const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 // Targets describe acceptance goals, not scores inherited from another category.
 const goals=[
 ['Factory-printable patterns','Pattern engineering','Prototype under validation','Print at 100% scale on letter/A4 and plotter sheets; maintain calibrated units, margins, grainlines and registration.','Print measured reference squares and known pattern dimensions; inspect assembled sheets and physical cut lines.','src/core/printLayout20261025.js','Pattern printing and registration cases exist; physical printer/plotter acceptance has not been established.'],
 ['Production cutting machine compatibility','Manufacturing','External factory acceptance needed','Output validated graded cutting files that real industrial CAD, marker and cutting operators can reliably reopen.','Independent receiving test on an actual cutter/marker workflow; confirm CUT outlines, notches, layers, units, and tolerances.','src/core/industrialPatternQA.js','Manufacturing DXF and receiver checks exist; no independent cutter production approval is established.'],
 ['Industrial 2D pattern construction','Pattern engineering','Integration and measurement gaps','Create, alter, and save complex patterns while preserving seam, dart, curve, internal-line and connected-source intent.','Round-trip representative factory-grade patterns, audit topology and seam/POM measurements through revisions.','src/core/exoPatternDraftConstruction20261023.js','Connected pattern operations exist, but Modaris/AccuMark manufacturing parity is not validated.'],
 ['Factory-grade multi-size grading','Grading','Size-set validation needed','Build editable grading rule tables with consistent shape, measurements, seam matches and notches across sizes.','Verify an independent multi-size ground-truth set with every affected size and factory review.','src/core/grading.js','Size-linked grading and related tests exist, not complete factory-grade acceptance.'],
 ['Realistic fabric simulation','Physical simulation','Physical correlation not established','Produce believable, repeatable drape, stretch, bend, thickness and motion driven by measured fabric properties.','Compare swatches and finished garments with physical fit/shape error tolerances, collision and solver stability tests.','src/core/clothcraftFabrics.js','Fabric and visual/simulation code exists; realistic physical equivalence remains unproven.'],
 ['Avatar fitting and garment clearance','3D fitting','Controlled validation needed','Inspect garment fit, pressure, clearance and ease on measurable avatars in multiple poses and sizes.','Compare known avatar measurements and physical fit sessions across motions; track penetration and strain.','src/core/metaHumanGlbBridge20261029.js','GLB bridge research exists; no validated complete Unreal fitting workflow.'],
 ['Complete official technical packs','Technical design','Factory handoff gate pending','Build clean multi-page tech packs with editable flats, BOM, measurements, grading, colorways, labels and revision notes.','Factory-review a real exported pack for completeness, accurate source links, version tracking and no clipped tables.','src/core/techPackWorkspacePrint.js','Pack generation and review checks exist, but official manufacturer acceptance is not proven.'],
 ['Technical flats and vector illustration','Technical design','Round-trip fidelity needed','Author Illustrator-style technical flats using pen paths, anchors, layers and editable line geometry.','Import/edit/save/export known source paths without losing topology or artwork.','src/core/techPackVectorArtwork20261031.js','Vector editing and flat paths exist; wider interoperability needs evidence.'],
 ['Interchange formats across CAD','Interoperability','File-specific compatibility needed','Safely import/export SVG, DXF, PDF, AI-derived assets and compatible 3D formats with truthful support levels.','Publish a pass/fail matrix using real fixtures; reject unsupported native objects without silent loss.','src/core/exoFileImportFormats20261101.js','File-format intake is under development; support varies by format and workflow.'],
 ['End-to-end 3D garment workspace','3D workspace','Workflow integration needed','Edit 2D patterns and inspect matching sewn 3D results with consistent saved project state.','Open-edit-simulate-save-reopen a complete sample project and compare geometry and render state.','src/core/garmentCodeImportPreflight.js','3D UI and import preflights exist; complete production-quality end-to-end workflow is not validated.'],
 ['Character and garment animation','Animation workspace','Research/prototype stage','Rig avatars and clothing for believable walk, pose, turn and animation playback with robust fabric follow-through.','Run a representative animated sequence with valid rigging, cloth collision and reproducible export.','src/core/metaHumanGlbBridge20261029.js','Avatar GLB intake research exists, but mature animated garment production is not demonstrated.'],
 ['Unreal Engine and MetaHuman workflows','External engine','Future integration target','Send compatible garments/avatar assets to Unreal Engine so a person can view their dressed avatar in an interactive scene.','Prove one actual Unreal/MetaHuman round-trip including skeletal mapping, cloth motion, materials and licensing constraints.','src/core/metaHumanGlbBridge20261029.js','GLB bridge is a starting point, not a functioning Unreal plugin or .uasset/.dna importer.'],
 ['Sharing and collaboration','Community and workflow','Hosted collaboration not established','Share projects, review notes, revisions and approved assets with granular roles and private-source protection.','Two-account permission tests; concurrent revisions, audit trail, conflict recovery and revoke/access checks.','integrations/clothcraft/agent-api.mjs','Workspace/API concepts exist; cross-user hosted sharing cannot be assumed from local demos.'],
 ['Reusable asset and pattern library','Project management','Source linkage needs validation','Maintain reusable patterns, fabrics, accessories and templates with licenses, searchable metadata and editable provenance.','Import, update, permission-check and re-open an asset across separate projects without broken dependencies.','src/core/clothcraftFabrics.js','Asset and fabric library paths exist; permission/provenance depth needs coverage.'],
 ['Native desktop reliability','Desktop','Platform qualification pending','Run long sessions on supported Macs with safe save/reopen, offline operation, crash recovery and signed releases.','Cold-start/install, stress tests, recovery and release artifact integrity on physical Macs.','integrations/clothcraft/macos','Mac native host/build integration exists; platform-wide certification is not established.'],
 ['Native/Rust parity and performance','Core architecture','Behavioral parity pending','Move suitable geometry and simulation work into authoritative native implementations without changing project results.','Golden-file parity tests, performance benchmarks and complete failure-mode coverage on actual project files.','src/core/rustFabricCostKernel.js','Rust-related modules and migrations exist; percentage of the entire migration is not independently established.'],
 ['Industrial documentation and standards','Quality systems','Evidence package incomplete','Publish repeatable definitions for units, POM, construction revisions, production checks and source identity.','Independent reviewers follow written steps and reproduce acceptance outcomes with archived evidence.','src/core/industrialPatternQA.js','Quality gates are under construction; factory approval is not inferred.'],
 ['Community ideas and voting','Community','Local prototype','Let community members post concepts, upvote, comment and participate in project priorities.','Multi-user authenticated backend, abuse controls, moderation, persistence and voting integrity.','website/clothcraft/marketplace/community-social.js','Current forum interactions are browser-local, not a public shared backend.']
 ];
 const stages={
 'Prototype under validation':1,'External factory acceptance needed':2,'Integration and measurement gaps':1,
 'Size-set validation needed':2,'Physical correlation not established':1,'Controlled validation needed':1,
 'Factory handoff gate pending':2,'Round-trip fidelity needed':2,'File-specific compatibility needed':2,
 'Workflow integration needed':1,'Research/prototype stage':0,'Future integration target':0,
 'Hosted collaboration not established':0,'Source linkage needs validation':1,'Platform qualification pending':2,
 'Behavioral parity pending':1,'Evidence package incomplete':1,'Local prototype':1};
 const gates=[
  ['Pattern source fidelity','Unverified externally','Reopen exact pattern geometry, units and edits in a separate implementation'],
  ['Factory production release','Not approved','Signed receipt, CUT contours, size coverage and factory sign-off'],
  ['Physical cloth correlation','Not established','Measured material testing against real sewn garments'],
  ['Desktop reliability','Not certified','Install, cold launch, long-session save/reopen, crash recovery and update tests'],
  ['Cross-user community','Local demo','Backend persistence, accounts, moderation and anti-abuse protections']
 ];
 try{
  const response=await fetch('/download/progress.json',{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);
  const data=await response.json(),systems=Array.isArray(data.systems)?data.systems:[];
  const map=new Map(systems.map(x=>[x.id,x]));
  const passed=systems.reduce((sum,x)=>sum+Number(x.passed||0),0),total=systems.reduce((sum,x)=>sum+Number(x.total||0),0);
  const pct=(a,b)=>b?Math.round(a/b*100):0;
  const cards=goals.map(([title,group,status,target,criteria,source,evidence],i)=>{
   const step=stages[status]??0;
   return `<article class="cc-detail-system cc-goal-card" data-stage="${step}"><div class="cc-detail-top"><span>${String(i+1).padStart(2,'0')} / ${safe(group)}</span><span class="cc-goal-stage">${safe(status)}</span></div><h3>${safe(title)}</h3><p class="cc-goal-target"><b>Target:</b> ${safe(target)}</p><div class="cc-goal-ladder" aria-label="Milestone stage ${step} of 4, qualitative not a completion percentage">${[0,1,2,3,4].map(n=>`<i class="${n<=step?'is-reached':''}"></i>`).join('')}</div><div class="cc-detail-sub">${['Research','Prototype','Internal validation','Independent acceptance','Production ready'][step]} · qualitative stage only</div><p class="cc-detail-next"><b>Acceptance test:</b> ${safe(criteria)}</p><p class="cc-goal-evidence"><b>Current evidence:</b> ${safe(evidence)}</p><p class="cc-goal-file">Implementation reference: <code>${safe(source)}</code></p></article>`;
  }).join('');
  root.innerHTML=`<div class="cc-detail-intro"><span class="cc-deep-kicker">04 / TARGET CAPABILITY ROADMAP</span><h2>From prototype to production.</h2><p>What ClothCraft must achieve to become a reliable real-world garment design studio. <strong>These are target outcomes and qualitative milestone stages, not recycled checkpoint percentages or unsupported completion claims.</strong> The eight measured percentages above remain the source-backed checkpoint snapshot.</p></div><div class="cc-detail-overview"><div><span>TRACKED CAPABILITY GOALS</span><strong>${goals.length}</strong><small>Across industrial CAD, 3D, animation and collaboration</small></div><div><span>INDEPENDENT FACTORY APPROVAL</span><strong>Pending</strong><small>No machine-ready certification claimed</small></div><div><span>REALISTIC FABRIC CORRELATION</span><strong>Pending</strong><small>Measured physical comparisons required</small></div><div><span>CHECKPOINT SNAPSHOT</span><strong>${pct(passed,total)}%</strong><small>${passed} / ${total}, separate from roadmap goals</small></div></div><div class="cc-detail-head"><h3>Capability targets &amp; acceptance criteria</h3><p>Each card explains the intended end state, what's available now, and the specific tests separating today's implementation from the target. The five-stage marker is a qualitative development phase, not a percentage.</p></div><div class="cc-goal-stage-legend"><span>Research</span><span>Prototype</span><span>Internal validation</span><span>Independent acceptance</span><span>Production ready</span></div><div class="cc-detail-grid cc-goal-grid">${cards}</div><div class="cc-detail-head"><h3>Hard release gates</h3><p>Factory acceptance, physical drape correlation, print calibration and multi-user access must be independently checked. A feature existing in code is not a substitute.</p></div><div class="cc-detail-gates">${gates.map(([title,status,criteria])=>`<div><strong>${safe(title)}</strong><span>${safe(status)}</span><p>${safe(criteria)}</p></div>`).join('')}</div><p class="cc-detail-foot">The only numerical engineering progress displayed here comes from the dated <a href="/download/progress.json">verification snapshot</a>, generated ${safe(data.generatedAt)}, source revision ${safe(data.sourceSha)}. The roadmap target phases are editorial judgments tied to documented gaps, not independently certified maturity ratings. No factory cutting approval or commercial CAD parity is implied.</p>`;

 }catch(error){root.innerHTML='<p class="cc-deep-note">The live progress snapshot is unavailable. Original checkpoint data remains linked from the Download page; no percentages have been inferred.</p>'}
})();
